{"op":"add","path":"/root","value":"onboarding-wizard"}
{"op":"add","path":"/elements/onboarding-wizard","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["intro","step-status","account-panel","preferences-panel","done-panel"]}}
{"op":"add","path":"/elements/intro","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["page-title","page-intro"]}}
{"op":"add","path":"/elements/page-title","value":{"type":"Heading","props":{"text":"Welcome — let’s get you set up","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/page-intro","value":{"type":"Text","props":{"text":"Complete these three quick steps to personalize your account.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/step-status","value":{"type":"Card","props":{"title":"Your progress","description":"You can move back to update any of your choices."},"children":["current-step-label","account-step-badge","preferences-step-badge","done-step-badge"]}}
{"op":"add","path":"/elements/current-step-label","value":{"type":"Text","props":{"text":{"$template":"Current step: ${/currentStep}"},"variant":"body"},"children":[]}}
{"op":"add","path":"/state/currentStep","value":"Account"}
{"op":"add","path":"/elements/account-step-badge","value":{"type":"Badge","props":{"text":"1 · Account","variant":{"$cond":{"$state":"/currentStep","eq":"Account"},"$then":"default","$else":"outline"}},"visible":{"$state":"/currentStep","eq":"Account"},"children":[]}}
{"op":"add","path":"/elements/account-step-inactive","value":{"type":"Badge","props":{"text":"1 · Account","variant":"outline"},"visible":{"$state":"/currentStep","neq":"Account"},"children":[]}}
{"op":"add","path":"/elements/preferences-step-badge","value":{"type":"Badge","props":{"text":"2 · Preferences","variant":"default"},"visible":{"$state":"/currentStep","eq":"Preferences"},"children":[]}}
{"op":"add","path":"/elements/preferences-step-inactive","value":{"type":"Badge","props":{"text":"2 · Preferences","variant":"outline"},"visible":{"$state":"/currentStep","neq":"Preferences"},"children":[]}}
{"op":"add","path":"/elements/done-step-badge","value":{"type":"Badge","props":{"text":"3 · Done","variant":"default"},"visible":{"$state":"/currentStep","eq":"Done"},"children":[]}}
{"op":"add","path":"/elements/done-step-inactive","value":{"type":"Badge","props":{"text":"3 · Done","variant":"outline"},"visible":{"$state":"/currentStep","neq":"Done"},"children":[]}}
{"op":"add","path":"/elements/account-panel","value":{"type":"Card","props":{"title":"Create your account","description":"Start with the details you’ll use to sign in."},"visible":{"$state":"/currentStep","eq":"Account"},"children":["account-fields","account-next"]}}
{"op":"add","path":"/elements/account-fields","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["full-name-input","email-input","password-input"]}}
{"op":"add","path":"/elements/full-name-input","value":{"type":"Input","props":{"label":"Full name","placeholder":"e.g. Alex Morgan","value":{"$bindState":"/account/fullName"}},"children":[]}}
{"op":"add","path":"/state/account","value":{"fullName":"","email":"","password":""}}
{"op":"add","path":"/elements/email-input","value":{"type":"Input","props":{"label":"Email address","type":"email","placeholder":"you@example.com","value":{"$bindState":"/account/email"}},"children":[]}}
{"op":"add","path":"/elements/password-input","value":{"type":"Input","props":{"label":"Password","type":"password","placeholder":"Choose a secure password","value":{"$bindState":"/account/password"}},"children":[]}}
{"op":"add","path":"/elements/account-next","value":{"type":"Button","props":{"label":"Continue to preferences","size":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"Preferences"}}},"children":[]}}
{"op":"add","path":"/elements/preferences-panel","value":{"type":"Card","props":{"title":"Set your preferences","description":"Choose what you’d like to hear about and how often."},"visible":{"$state":"/currentStep","eq":"Preferences"},"children":["preference-fields","preferences-navigation"]}}
{"op":"add","path":"/elements/preference-fields","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["digest-choice","interest-choice","product-updates"]}}
{"op":"add","path":"/elements/digest-choice","value":{"type":"RadioGroup","props":{"label":"Email digest frequency","options":["Weekly summary","Monthly roundup","No digest"],"value":{"$bindState":"/preferences/digest"}},"children":[]}}
{"op":"add","path":"/state/preferences","value":{"digest":"Weekly summary","interest":"Product design","productUpdates":true}}
{"op":"add","path":"/elements/interest-choice","value":{"type":"Select","props":{"label":"Primary interest","placeholder":"Choose a topic","options":["Product design","Research","Engineering","Leadership"],"value":{"$bindState":"/preferences/interest"}},"children":[]}}
{"op":"add","path":"/elements/product-updates","value":{"type":"Switch","props":{"label":"Product updates","description":"Get occasional notes about new features and improvements.","checked":{"$bindState":"/preferences/productUpdates"}},"children":[]}}
{"op":"add","path":"/elements/preferences-navigation","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"center"},"children":["preferences-back","preferences-next"]}}
{"op":"add","path":"/elements/preferences-back","value":{"type":"Button","props":{"label":"Back","variant":"outline"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"Account"}}},"children":[]}}
{"op":"add","path":"/elements/preferences-next","value":{"type":"Button","props":{"label":"Finish setup"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"Done"}}},"children":[]}}
{"op":"add","path":"/elements/done-panel","value":{"type":"Card","props":{"title":"You’re all set","description":"Your account is ready. You can change these preferences any time."},"visible":{"$state":"/currentStep","eq":"Done"},"children":["success-notice","account-summary","done-back"]}}
{"op":"add","path":"/elements/success-notice","value":{"type":"Alert","props":{"title":"Setup complete","description":"Thanks for taking a moment to personalize your experience.","variant":"default"},"children":[]}}
{"op":"add","path":"/elements/account-summary","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["summary-name","summary-email","summary-digest","summary-interest"]}}
{"op":"add","path":"/elements/summary-name","value":{"type":"Text","props":{"text":{"$template":"Account name: ${/account/fullName}"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/summary-email","value":{"type":"Text","props":{"text":{"$template":"Email: ${/account/email}"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/summary-digest","value":{"type":"Text","props":{"text":{"$template":"Digest: ${/preferences/digest}"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/summary-interest","value":{"type":"Text","props":{"text":{"$template":"Interest: ${/preferences/interest}"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/done-back","value":{"type":"Button","props":{"label":"Back to preferences","variant":"outline"},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":"Preferences"}}},"children":[]}}
